1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
27	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
28	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
29	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
30	  .empty { color: #616e7c; }
31	  .list-error { color: #9b1c1c; }
32	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
33	  .meta { color: #7b8794; font-size: .85rem; }
34	</style>
35	<main>
36	  <h1>ScoreArena</h1>
37	  <p class="sub">桌面规则游戏与赛事管理</p>
38	
39	  <h2>创建公开房间</h2>
40	  <form id="room-form" novalidate>
41	    <div class="field">
42	      <label for="name">房间名称</label>
43	      <input id="name" name="name" type="text" autocomplete="off"
44	             placeholder="1–40 个字符，首尾空白会被去掉" required>
45	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
46	    </div>
47	    <div class="field">
48	      <label for="game">游戏规则</label>
49	      <select id="game" name="game" required>
50	        <option value="" selected>请选择游戏规则…</option>
51	        <option value="gomoku">五子棋（gomoku）</option>
52	        <option value="ludo">飞行棋（ludo）</option>
53	      </select>
54	    </div>
55	    <div class="field">
56	      <label for="capacity">人数上限</label>
57	      <select id="capacity" name="capacity" required disabled>
58	        <option value="" selected>请先选择游戏规则</option>
59	      </select>
60	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
61	    </div>
62	    <div class="field">
63	      <label for="turnSeconds">每步时间限制</label>
64	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
65	             placeholder="秒，0 表示不限时" required>
66	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
67	    </div>
68	    <div class="field">
69	      <div></div>
70	      <div class="actions">
71	        <button type="submit" id="submit">创建房间</button>
72	      </div>
73	    </div>
74	    <p class="msg" id="form-msg" role="alert"></p>
75	  </form>
76	
77	  <h2>房间列表</h2>
78	  <div id="list-area">
79	    <p class="empty" id="empty-tip">还没有房间记录。</p>
80	  </div>
81	
82	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
83	</main>
84	
85	<script>
86	(function () {
87	  var form = document.getElementById('room-form');
88	  var gameSel = document.getElementById('game');
89	  var capSel = document.getElementById('capacity');
90	  var capHint = document.getElementById('capacity-hint');
91	  var submitBtn = document.getElementById('submit');
92	  var formMsg = document.getElementById('form-msg');
93	  var listArea = document.getElementById('list-area');
94	  var emptyTip = document.getElementById('empty-tip');
95	
96	  var GAME_LABELS = { gomoku: '五子棋', ludo: '飞行棋' };
97	  var STATUS_LABELS = { waiting: '未开始' };
98	
99	  // 按所选规则重建人数上限选项。
100	  function syncCapacity() {
101	    var game = gameSel.value;
102	    var prev = capSel.value;
103	    capSel.innerHTML = '';
104	    if (game === 'gomoku') {
105	      capSel.disabled = false;
106	      addOption('', '固定 2 人');
107	      addOption('2', '2 人');
108	      capSel.value = '2';
109	      capHint.textContent = '五子棋人数上限固定为 2 人。';
110	    } else if (game === 'ludo') {
111	      capSel.disabled = false;
112	      addOption('', '请选择人数上限…');
113	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
114	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
115	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
116	    } else {
117	      capSel.disabled = true;
118	      addOption('', '请先选择游戏规则');
119	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
120	    }
121	  }
122	
123	  function addOption(value, text) {
124	    var opt = document.createElement('option');
125	    opt.value = value;
126	    opt.textContent = text;
127	    capSel.appendChild(opt);
128	  }
129	
130	  gameSel.addEventListener('change', syncCapacity);
131	
132	  function showMessage(kind, text) {
133	    formMsg.className = 'msg show ' + kind;
134	    formMsg.textContent = text;
135	  }
136	  function clearMessage() {
137	    formMsg.className = 'msg';
138	    formMsg.textContent = '';
139	  }
140	
141	  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
142	  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
143	  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
144	  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
145	  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
146	  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
147	  function trimName(value) {
148	    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
149	  }
150	
151	  // 与服务端一致的提交前校验；服务端仍会再次校验。
152	  function validate(payload) {
153	    var nameLen = Array.from(trimName(payload.name)).length;
154	    if (nameLen === 0) return '房间名称不能为空。';
155	    if (nameLen > 40) return '房间名称去掉首尾空白后不能超过 40 个字符。';
156	    if (payload.game !== 'gomoku' && payload.game !== 'ludo') return '请选择游戏规则。';
157	    if (payload.game === 'gomoku' && payload.capacity !== 2) return '五子棋的人数上限固定为 2 人。';
158	    if (payload.game === 'ludo' && !(payload.capacity >= 2 && payload.capacity <= 4)) {
159	      return '飞行棋的人数上限必须为 2 至 4 人。';
160	    }
161	    var t = payload.turnSeconds;
162	    if (t !== 0 && !(Number.isInteger(t) && t >= 10 && t <= 600)) {
163	      return '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。';
164	    }
165	    return null;
166	  }
167	
168	  form.addEventListener('submit', function (event) {
169	    event.preventDefault();
170	    clearMessage();
171	
172	    var nameInput = document.getElementById('name');
173	    var turnInput = document.getElementById('turnSeconds');
174	    var turnRaw = turnInput.value.trim();
175	    var payload = {
176	      name: nameInput.value,
177	      game: gameSel.value,
178	      capacity: capSel.value === '' ? null : parseInt(capSel.value, 10),
179	      turnSeconds: turnRaw === '' ? null : Number(turnRaw)
180	    };
181	
182	    // 漏填要明确报错，绝不补默认值；名称只含会被去掉的首尾空白时同样视为空。
183	    if (trimName(payload.name) === '') return showMessage('error', '房间名称不能为空。'), false;
184	    if (!payload.game) return showMessage('error', '请选择游戏规则。'), false;
185	    if (payload.capacity === null) return showMessage('error', '请选择人数上限。'), false;
186	    if (turnRaw === '') return showMessage('error', '请填写每步时间限制（0 表示不限时）。'), false;
187	    if (!/^-?\d+$/.test(turnRaw)) return showMessage('error', '时间限制必须是整数秒，不能含小数。'), false;
188	
189	    var problem = validate({
190	      name: payload.name,
191	      game: payload.game,
192	      capacity: payload.capacity,
193	      turnSeconds: Number(turnRaw)
194	    });
195	    if (problem) { showMessage('error', problem); return; }
196	
197	    payload.turnSeconds = Number(turnRaw);
198	    submit(payload);
199	  });
200	
201	  function submit(payload) {
202	    submitBtn.disabled = true;
203	    fetch('/api/rooms', {
204	      method: 'POST',
205	      headers: { 'Content-Type': 'application/json' },
206	      body: JSON.stringify(payload)
207	    }).then(function (resp) {
208	      return resp.json().catch(function () { return {}; }).then(function (data) {
209	        return { ok: resp.ok, status: resp.status, data: data };
210	      });
211	    }).then(function (result) {
212	      if (result.ok && result.status === 201) {
213	        showMessage('ok', '房间已创建，编号：' + result.data.id);
214	        form.reset();
215	        syncCapacity();
216	        return loadRooms();
217	      }
218	      // 创建失败：保留填写内容，仅显示原因。
219	      var reason = result.data && result.data.error ? result.data.error
220	                 : ('创建失败（HTTP ' + result.status + '）');
221	      showMessage('error', reason);
222	    }).catch(function () {
223	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
224	    }).finally(function () {
225	      submitBtn.disabled = false;
226	    });
227	  }
228	
229	  function formatTime(iso) {
230	    var d = new Date(iso);
231	    if (isNaN(d.getTime())) return iso;
232	    var pad = function (n) { return String(n).padStart(2, '0'); };
233	    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
234	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
235	    return { text: text, title: iso };
236	  }
237	
238	  function renderRooms(rooms) {
239	    listArea.innerHTML = '';
240	    if (!rooms.length) {
241	      var p = document.createElement('p');
242	      p.className = 'empty';
243	      p.textContent = '还没有房间记录。';
244	      listArea.appendChild(p);
245	      return;
246	    }
247	    var table = document.createElement('table');
248	    table.innerHTML =
249	      '<thead><tr>' +
250	      '<th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th>' +
251	      '<th>时间限制</th><th>状态</th><th>创建时间</th>' +
252	      '</tr></thead>';
253	    var tbody = document.createElement('tbody');
254	    rooms.forEach(function (r) {
255	      var tr = document.createElement('tr');
256	
257	      var tdId = document.createElement('td');
258	      tdId.className = 'id';
259	      tdId.textContent = r.id || '';
260	      tr.appendChild(tdId);
261	
262	      var tdName = document.createElement('td');
263	      tdName.textContent = r.name || '';
264	      tr.appendChild(tdName);
265	
266	      var tdGame = document.createElement('td');
267	      tdGame.textContent = GAME_LABELS[r.game] || r.game || '';
268	      tr.appendChild(tdGame);
269	
270	      var tdCap = document.createElement('td');
271	      tdCap.textContent = (r.capacity != null ? r.capacity : '') + ' 人';
272	      tr.appendChild(tdCap);
273	
274	      var tdTurn = document.createElement('td');
275	      if (r.turnSeconds === 0) tdTurn.textContent = '不限时';
276	      else tdTurn.textContent = r.turnSeconds + ' 秒';
277	      tr.appendChild(tdTurn);
278	
279	      var tdStatus = document.createElement('td');
280	      var badge = document.createElement('span');
281	      badge.className = 'badge';
282	      badge.textContent = STATUS_LABELS[r.status] || r.status || '';
283	      tdStatus.appendChild(badge);
284	      tr.appendChild(tdStatus);
285	
286	      var tdTime = document.createElement('td');
287	      var t = formatTime(r.createdAt || '');
288	      tdTime.textContent = t.text;
289	      tdTime.title = t.title;
290	      tr.appendChild(tdTime);
291	
292	      tbody.appendChild(tr);
293	    });
294	    table.appendChild(tbody);
295	    listArea.appendChild(table);
296	  }
297	
298	  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
299	  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
300	  // 防止旧数据覆盖新查询已展示的列表。
301	  var listQuerySeq = 0;
302	
303	  function loadRooms() {
304	    var seq = ++listQuerySeq;
305	    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
306	      .then(function (resp) {
307	        if (!resp.ok) throw new Error('HTTP ' + resp.status);
308	        return resp.json();
309	      })
310	      .then(function (data) {
311	        if (seq !== listQuerySeq) return;
312	        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
313	        renderRooms(rooms);
314	      })
315	      .catch(function () {
316	        if (seq !== listQuerySeq) return;
317	        listArea.innerHTML = '';
318	        var p = document.createElement('p');
319	        p.className = 'list-error';
320	        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
321	        listArea.appendChild(p);
322	      });
323	  }
324	
325	  syncCapacity();
326	  loadRooms();
327	})();
328	</script>
329	</html>
