import { strict as assert } from 'node:assert';
import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import puppeteer from 'puppeteer-core';

const repoRoot = '/opt/gsb-production/workspaces/coco/prod-17/A/task012';
const dir = await mkdtemp(path.join(tmpdir(), 'skip-check-'));
const bin = path.join(dir, 'score-arena');
await promisify(execFile)('go', ['build', '-o', bin, '.'], { cwd: repoRoot });

function start(dataDir) {
  const proc = spawn(bin, ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
    { stdio: ['ignore', 'pipe', 'inherit'] });
  return { proc, ready: new Promise((res, rej) => {
    let buf = '';
    const t = setTimeout(() => rej(new Error('timeout')), 15000);
    proc.stdout.on('data', (c) => { buf += c; const m = buf.match(/listening on (http:\/\/\S+)/); if (m) { clearTimeout(t); res(m[1]); } });
  }) };
}

const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome', headless: true,
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });

async function readList(page) {
  return page.evaluate(() => {
    const area = document.getElementById('list-area');
    const rows = [...document.querySelectorAll('#list-area table tbody tr')].map(tr =>
      [...tr.querySelectorAll('td')].slice(0, 3).map(td => td.textContent));
    return {
      rows,
      text: area.textContent,
      skip: document.querySelector('#list-area .skip-notice')?.textContent || null,
      empty: document.querySelector('#list-area .empty')?.textContent || null,
      error: document.querySelector('#list-area .list-error')?.textContent || null,
    };
  });
}

// ---- Case 1: mixed records ----
const dataDir = await mkdtemp(path.join(tmpdir(), 'rooms-mixed-'));
const rawContent = '[\n' + [
  '{"id":"r1","name":"正常房间甲","game":"gomoku","capacity":2,"turnSeconds":0,"status":"waiting","createdAt":"2026-01-01T00:00:00Z","note":"附加字段保留"}',
  'null',
  '"我是字符串"',
  '42',
  'true',
  '["我","是","数组"]',
  '{"id":"r2","name":"正常房间乙","game":"ludo","capacity":3,"turnSeconds":60,"status":"waiting","createdAt":"2026-01-02T00:00:00Z","extra":{"x":1},"tags":["a"]}',
].join(',\n') + '\n]\n';
await writeFile(path.join(dataDir, 'rooms.json'), rawContent);
const srv = start(dataDir);
const base = await srv.ready;
const page = await browser.newPage();
await page.goto(base, { waitUntil: 'load' });
await page.waitForSelector('#list-area table tbody tr');

let list = await readList(page);
assert.deepEqual(list.rows, [
  ['r1', '正常房间甲', '五子棋'],
  ['r2', '正常房间乙', '飞行棋'],
], '正常房间应按原顺序展示，附加字段不影响');
assert.ok(list.skip && list.skip.includes('5 条'), '应提示 5 条未展示，实际: ' + list.skip);
assert.ok(list.skip.includes('原始数据仍保留'), '应说明原始数据仍保留');
assert.equal(list.empty, null);
assert.equal(list.error, null);

// 原始数据文件未被改写或重排
assert.equal(await readFile(path.join(dataDir, 'rooms.json'), 'utf8'), rawContent, '服务端原始数据必须原样保留');

// ---- Case 2: 创建新房间后，提示随新结果更新，成功提示不被覆盖 ----
await page.type('#name', '新建房间');
await page.select('#game', 'ludo');
await page.select('#capacity', '2');
await page.type('#turnSeconds', '30');
await page.click('#submit');
await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'));
await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 3);
const msg = await page.$eval('#form-msg', el => el.textContent);
assert.ok(msg.startsWith('房间已创建，编号：'), '创建成功提示保留: ' + msg);
list = await readList(page);
assert.equal(list.rows.length, 3, '新旧房间一起展示');
assert.ok(list.skip && list.skip.includes('5 条'), '刷新后仍按本次结果提示 5 条');
assert.ok(!list.skip.includes('还没有房间记录'));

// ---- Case 3: 拦截返回全部无法展示的元素 ----
await page.setRequestInterception(true);
page.on('request', (req) => {
  if (req.method() === 'GET' && req.url().endsWith('/api/rooms')) {
    req.respond({ status: 200, contentType: 'application/json', body: JSON.stringify({ rooms: [null, 'x', 1, false, []] }) });
  } else req.continue();
});
await page.evaluate(() => location.reload());
await page.waitForSelector('#list-area .skip-notice');
list = await readList(page);
assert.equal(list.rows.length, 0);
assert.ok(!list.hasTable);
assert.equal(list.empty, null, '不能显示“还没有房间记录”');
assert.ok(list.skip.includes('没有可展示的房间'), '应说明没有可展示的房间: ' + list.skip);
assert.ok(list.skip.includes('5 条'), '应保留未展示数量');
assert.equal(list.error, null, '不能误报为加载失败');

// ---- Case 4: 下一次成功查询无跳过元素时，旧提示必须消失 ----
let first = true;
page.removeAllListeners('request');
page.on('request', (req) => {
  if (first && req.method() === 'GET' && req.url().endsWith('/api/rooms')) {
    first = false;
    req.respond({ status: 200, contentType: 'application/json', body: JSON.stringify({ rooms: [{ id: 'z1', name: '仅正常', game: 'gomoku', capacity: 2, turnSeconds: 0, status: 'waiting', createdAt: '2026-03-01T00:00:00Z' }] }) });
  } else req.continue();
});
await page.evaluate(() => location.reload());
await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 1);
list = await readList(page);
assert.equal(list.skip, null, '上次的跳过数量不能残留');
assert.equal(list.empty, null);
assert.equal(list.error, null);

// ---- Case 5: 真空数组只显示原空列表提示 ----
await page.setRequestInterception(false);
page.removeAllListeners('request');
const dataDir2 = await mkdtemp(path.join(tmpdir(), 'rooms-empty-'));
await writeFile(path.join(dataDir2, 'rooms.json'), '[]\n');
const srv2 = start(dataDir2);
const base2 = await srv2.ready;
const page2 = await browser.newPage();
await page2.goto(base2, { waitUntil: 'load' });
await page2.waitForSelector('#list-area .empty');
list = await readList(page2);
assert.equal(list.empty, '还没有房间记录。');
assert.equal(list.skip, null, '真空数组不应有跳过提示');
assert.equal(list.error, null);

await browser.close();
srv.proc.kill('SIGKILL'); srv2.proc.kill('SIGKILL');
await rm(dir, { recursive: true, force: true });
await rm(dataDir, { recursive: true, force: true });
await rm(dataDir2, { recursive: true, force: true });
console.log('ALL NEW-BEHAVIOR CHECKS PASSED');

